@php
 $groups=$turnoPayments->groupBy(fn($p)=>\Carbon\Carbon::parse($p->created_at)->format('Y-m-d H:00'));$buckets=collect();
 if($turno){$start=\Carbon\Carbon::parse($turno->abierta_at)->startOfHour();$end=\Carbon\Carbon::parse($turno->cerrada_at??now())->startOfHour();foreach(\Carbon\CarbonPeriod::create($start,'1 hour',max($start,$end)) as $hour){$key=$hour->format('Y-m-d H:00');$group=$groups->get($key,collect());$buckets->push(['label'=>$hour->format('H:i'),'date'=>$hour->format('d/m/Y H:i'),'amount'=>(float)$group->sum('importe'),'count'=>$group->count()]);}}
 $chartWidth=max(590,$buckets->count()*55+110);$plotHeight=154;$plotWidth=$chartWidth-105;$maxAmount=max(100,ceil(($buckets->max('amount')??0)/100)*100);$maxOps=max(4,ceil(($buckets->max('count')??0)/4)*4);$step=$plotWidth/max(1,$buckets->count());$points=[];
 foreach($buckets as $i=>$bucket)$points[]=(60+$step*($i+.5)).','.round(184-$bucket['count']/$maxOps*$plotHeight,2);
@endphp
<div class="ct-chart-legend"><span><i class="ct-bar-key"></i>Importes cobrados ($ MXN)</span><span><i class="ct-line-key"></i>Operaciones</span></div>
